💡 <b>Доступно с ES2020!</b>

🍛 <b>Каррирование — преобразование f(a,b,c) в f(a)(b)(c)</b>

<b>Обычная функция:</b>
<code>function sum(a, b, c) {
  return a + b + c;
}

sum(1, 2, 3); // 6</code>

<b>Каррированная функция:</b>
<code>function curriedSum(a) {
  return function(b) {
    return function(c) {
      return a + b + c;
    };
  };
}

curriedSum(1)(2)(3); // 6

// Или стрелочные функции
const curriedSum = a => b => c => a + b + c;</code>

<b>Универсальная функция каррирования:</b>
<code>function curry(fn) {
  return function curried(...args) {
    if (args.length >= fn.length) {
      return fn.apply(this, args);
    }
    return function(...nextArgs) {
      return curried.apply(this, args.concat(nextArgs));
    };
  };
}

const sum = (a, b, c) => a + b + c;
const curriedSum = curry(sum);

curriedSum(1)(2)(3); // 6
curriedSum(1, 2)(3); // 6
curriedSum(1)(2, 3); // 6</code>

<b>Практическое применение:</b>
<code>// Конфигурация логгера
const log = level => message => time => {
  console.log(`[${time}] ${level}: ${message}`);
};

const errorLog = log('ERROR');
const infoLog = log('INFO');

errorLog('Ошибка сервера')(new Date());
infoLog('Запрос обработан')(new Date());</code>

💡 <b>Каррирование создаёт переиспользуемые функции!</b>

🧠 <b>Мемоизация — кеширование результатов функций</b>

<b>Проблема:</b>
<code>function fibonacci(n) {
  if (n <= 1) return n;
  return fibonacci(n - 1) + fibonacci(n - 2);
}

fibonacci(40); // Очень медленно! 🐌</code>

<b>Решение — мемоизация:</b>
<code>function memoize(fn) {
  const cache = {};

  return function(...args) {
    const key = JSON.stringify(args);

    if (key in cache) {
      console.log('Из кеша');
      return cache[key];
    }

    const result = fn.apply(this, args);
    cache[key] = result;
    return result;
  };
}

const fibonacci = memoize(function(n) {
  if (n <= 1) return n;
  return fibonacci(n - 1) + fibonacci(n - 2);
});

fibonacci(40); // Быстро! ⚡</code>

<b>С Map (лучше):</b>
<code>function memoize(fn) {
  const cache = new Map();

  return function(...args) {
    const key = JSON.stringify(args);

    if (cache.has(key)) {
      return cache.get(key);
    }

    const result = fn(...args);
    cache.set(key, result);
    return result;
  };
}</code>

<b>Пример с API:</b>
<code>const fetchUser = memoize(async (id) => {
  const response = await fetch(`/api/users/${id}`);
  return response.json();
});

// Первый вызов — запрос к API
await fetchUser(1);

// Второй вызов — из кеша
await fetchUser(1);</code>

💡 <b>React.memo и useMemo используют мемоизацию!</b>

⏱️ <b>Debounce и Throttle — ограничение вызовов функций</b>

<b>Debounce (задержка):</b>
Вызывает функцию только после того, как прошло N мс с последнего вызова.

<code>function debounce(fn, delay) {
  let timeoutId;

  return function(...args) {
    clearTimeout(timeoutId);
    timeoutId = setTimeout(() => fn.apply(this, args), delay);
  };
}

// Поиск при вводе
const search = debounce((query) => {
  console.log('Поиск:', query);
}, 500);

input.addEventListener('input', (e) => search(e.target.value));
// Запрос отправится только через 500мс после остановки ввода</code>

<b>Throttle (ограничение):</b>
Вызывает функцию не чаще, чем раз в N мс.

<code>function throttle(fn, delay) {
  let lastCall = 0;

  return function(...args) {
    const now = Date.now();

    if (now - lastCall >= delay) {
      lastCall = now;
      fn.apply(this, args);
    }
  };
}

// Обработка скролла
const handleScroll = throttle(() => {
  console.log('Скролл:', window.scrollY);
}, 200);

window.addEventListener('scroll', handleScroll);
// Вызовется максимум раз в 200мс</code>

<b>Когда использовать:</b>
• Debounce: поиск, автосохранение, валидация
• Throttle: скролл, ресайз, mousemove

💡 <b>Lodash имеет готовые _.debounce и _.throttle!</b>

🚀 <b>IIFE — Immediately Invoked Function Expression</b>

<b>Что это:</b>
Функция, которая выполняется сразу после создания.

<b>Синтаксис:</b>
<code>// Классический IIFE
(function() {
  console.log('Выполнилось сразу!');
})();

// Со стрелочной функцией
(() => {
  console.log('Тоже сразу!');
})();

// С параметрами
((name) => {
  console.log(`Привет, ${name}!`);
})('John');</code>

<b>Зачем нужен:</b>

<b>1. Изоляция переменных:</b>
<code>(function() {
  const secret = 'Секрет';
  console.log(secret);
})();

console.log(secret); // ❌ ReferenceError</code>

<b>2. Избежание глобального загрязнения:</b>
<code>// До ES6 модулей
(function() {
  const myLibrary = {
    version: '1.0.0',
    doSomething() {}
  };

  window.MyLibrary = myLibrary;
})();</code>

<b>3. Создание приватных переменных:</b>
<code>const counter = (function() {
  let count = 0; // Приватная

  return {
    increment() { return ++count; },
    decrement() { return --count; },
    getCount() { return count; }
  };
})();

counter.increment(); // 1
counter.increment(); // 2
console.log(counter.count); // undefined ✅</code>

<b>Современная альтернатива:</b>
<code>// Блоки с let/const
{
  const secret = 'Секрет';
  console.log(secret);
}

// ES6 модули
export const myFunction = () => {};</code>

💡 <b>IIFE был популярен до ES6 модулей!</b>

🔁 <b>Рекурсия — функция вызывает сама себя</b>

<b>Обычная рекурсия:</b>
<code>function factorial(n) {
  if (n <= 1) return 1; // Базовый случай
  return n * factorial(n - 1); // Рекурсивный вызов
}

factorial(5); // 120
// 5 * 4 * 3 * 2 * 1</code>

<b>Проблема — переполнение стека:</b>
<code>factorial(10000); // ❌ RangeError: Maximum call stack size exceeded</code>

<b>Хвостовая рекурсия:</b>
Рекурсивный вызов — последняя операция в функции.

<code>function factorial(n, acc = 1) {
  if (n <= 1) return acc;
  return factorial(n - 1, n * acc); // Хвостовой вызов
}

factorial(5); // 120</code>

<b>Почему хвостовая рекурсия лучше:</b>
• Компилятор может оптимизировать (TCO)
• Не создаёт новые фреймы в стеке
• Работает как цикл

<b>⚠️ В JavaScript:</b>
TCO (Tail Call Optimization) поддерживается только в strict mode и не во всех движках.

<b>Альтернатива — цикл:</b>
<code>function factorial(n) {
  let result = 1;
  for (let i = 2; i <= n; i++) {
    result *= i;
  }
  return result;
}

factorial(10000); // ✅ Работает</code>

<b>Примеры рекурсии:</b>
<code>// Обход дерева
function traverse(node) {
  console.log(node.value);
  node.children.forEach(traverse);
}

// Глубокое клонирование
function deepClone(obj) {
  if (typeof obj !== 'object') return obj;
  const clone = Array.isArray(obj) ? [] : {};
  for (let key in obj) {
    clone[key] = deepClone(obj[key]);
  }
  return clone;
}</code>

💡 <b>Рекурсия красива, но цикл часто эффективнее!</b>

🎼 <b>Композиция — объединение функций</b>

<b>Идея:</b>
Создать новую функцию из нескольких, где результат одной передаётся в другую.

<b>Ручная композиция:</b>
<code>const add = x => x + 2;
const multiply = x => x * 3;
const subtract = x => x - 1;

// Вложенные вызовы (справа налево)
const result = subtract(multiply(add(5)));
// add(5) = 7
// multiply(7) = 21
// subtract(21) = 20</code>

<b>Функция compose:</b>
<code>const compose = (...fns) => x => 
  fns.reduceRight((acc, fn) => fn(acc), x);

const calculate = compose(subtract, multiply, add);
calculate(5); // 20</code>

<b>Функция pipe (слева направо):</b>
<code>const pipe = (...fns) => x => 
  fns.reduce((acc, fn) => fn(acc), x);

const calculate = pipe(add, multiply, subtract);
calculate(5); // 20</code>

<b>Практический пример:</b>
<code>// Обработка данных
const trim = str => str.trim();
const toLowerCase = str => str.toLowerCase();
const removeSpaces = str => str.replace(/\s+/g, '-');

const slugify = pipe(trim, toLowerCase, removeSpaces);

slugify('  Hello World  '); // 'hello-world'</code>

<b>С async функциями:</b>
<code>const composeAsync = (...fns) => x => 
  fns.reduceRight(
    (acc, fn) => acc.then(fn),
    Promise.resolve(x)
  );

const fetchUser = id => fetch(`/api/users/${id}`);
const parseJSON = res => res.json();
const getName = user => user.name;

const getUserName = composeAsync(getName, parseJSON, fetchUser);
await getUserName(1); // 'John'</code>

💡 <b>Композиция — основа функционального программирования!</b>

📝 <b>Оператор запятая — выполнение нескольких выражений</b>

<b>Как работает:</b>
Выполняет выражения слева направо и возвращает результат последнего.

<code>let x = (1, 2, 3);
console.log(x); // 3

let y = (console.log('a'), console.log('b'), 5);
// Выведет: 'a', 'b'
console.log(y); // 5</code>

<b>В циклах:</b>
<code>for (let i = 0, j = 10; i < 5; i++, j--) {
  console.log(i, j);
}
// 0 10
// 1 9
// 2 8
// 3 7
// 4 6</code>

<b>С return:</b>
<code>function test() {
  return (console.log('Выполнено'), 42);
}

const result = test(); // Выведет 'Выполнено'
console.log(result); // 42</code>

<b>⚠️ Не путать с аргументами:</b>
<code>// Запятая в аргументах — это разделитель
func(1, 2, 3); // 3 аргумента

// Оператор запятая
func((1, 2, 3)); // 1 аргумент со значением 3</code>

💡 <b>Редко используется, но полезно знать!</b>

🏷️ <b>Label — метки для циклов</b>

<b>Синтаксис:</b>
<code>labelName: statement</code>

<b>Выход из вложенных циклов:</b>
<code>outer: for (let i = 0; i < 3; i++) {
  for (let j = 0; j < 3; j++) {
    if (i === 1 && j === 1) {
      break outer; // Выход из обоих циклов
    }
    console.log(i, j);
  }
}
// Вывод: 0 0, 0 1, 0 2, 1 0</code>

<b>Continue с меткой:</b>
<code>outer: for (let i = 0; i < 3; i++) {
  for (let j = 0; j < 3; j++) {
    if (j === 1) {
      continue outer; // Переход к следующей итерации outer
    }
    console.log(i, j);
  }
}
// Вывод: 0 0, 1 0, 2 0</code>

<b>С блоками:</b>
<code>myBlock: {
  console.log('1');
  break myBlock; // Выход из блока
  console.log('2'); // Не выполнится
}
console.log('3');</code>

<b>⚠️ Не злоупотребляйте:</b>
Метки делают код менее читаемым. Лучше использовать функции.

💡 <b>Полезно для сложных вложенных циклов!</b>

🕳️ <b>void — возвращает undefined</b>

<b>Синтаксис:</b>
<code>void expression</code>

<b>Всегда возвращает undefined:</b>
<code>console.log(void 0); // undefined
console.log(void 1); // undefined
console.log(void 'hello'); // undefined
console.log(void (2 + 2)); // undefined</code>

<b>Применение — безопасный undefined:</b>
<code>// undefined можно переопределить (в старом JS)
let undefined = 'not undefined'; // ⚠️

// void 0 всегда undefined
if (value === void 0) {}

// Современный способ
if (value === undefined) {} // ✅</code>

<b>В ссылках:</b>
<code>&lt;a href="javascript:void(0)" onclick="doSomething()"&gt;
  Кликни
&lt;/a&gt;
// Предотвращает переход по ссылке</code>

<b>IIFE без скобок:</b>
<code>void function() {
  console.log('IIFE');
}();</code>

💡 <b>Редко используется в современном JS!</b>

🏗️ <b>instanceof — проверка принадлежности к классу</b>

<b>Базовое использование:</b>
<code>class User {}
const user = new User();

console.log(user instanceof User); // true
console.log(user instanceof Object); // true (цепочка прототипов)</code>

<b>С встроенными типами:</b>
<code>[] instanceof Array; // true
[] instanceof Object; // true

{} instanceof Object; // true

new Date() instanceof Date; // true
/regex/ instanceof RegExp; // true</code>

<b>⚠️ Не работает с примитивами:</b>
<code>'hello' instanceof String; // false
42 instanceof Number; // false
true instanceof Boolean; // false

// Но работает с обёртками
new String('hello') instanceof String; // true</code>

<b>С наследованием:</b>
<code>class Animal {}
class Dog extends Animal {}

const dog = new Dog();

dog instanceof Dog; // true
dog instanceof Animal; // true
dog instanceof Object; // true</code>

<b>Кастомная проверка:</b>
<code>class MyClass {
  static [Symbol.hasInstance](obj) {
    return obj.customProperty === true;
  }
}

const obj = { customProperty: true };
obj instanceof MyClass; // true</code>

💡 <b>instanceof проверяет цепочку прототипов!</b>

🗑️ <b>delete — удаление свойств объекта</b>

<b>Удаление свойств:</b>
<code>const user = { name: 'John', age: 30, city: 'NY' };

delete user.age;
console.log(user); // { name: 'John', city: 'NY' }

delete user['city'];
console.log(user); // { name: 'John' }</code>

<b>Возвращаемое значение:</b>
<code>const obj = { prop: 1 };

delete obj.prop; // true (успешно)
delete obj.nonExistent; // true (свойства нет)
delete obj.toString; // true (но не удалится из прототипа)</code>

<b>⚠️ Нельзя удалить:</b>
<code>// Переменные
let x = 10;
delete x; // false (в strict mode — ошибка)

// Свойства прототипа
const obj = {};
delete obj.toString; // true, но toString остался

// Элементы массива (оставляет дыру)
const arr = [1, 2, 3];
delete arr[1];
console.log(arr); // [1, empty, 3]
console.log(arr.length); // 3 ⚠️</code>

<b>Для массивов используйте splice:</b>
<code>const arr = [1, 2, 3];
arr.splice(1, 1); // Удалить 1 элемент с индекса 1
console.log(arr); // [1, 3]
console.log(arr.length); // 2 ✅</code>

💡 <b>delete для объектов, splice для массивов!</b>

🆕 <b>new — создание экземпляра объекта</b>

<b>Что делает new:</b>
1. Создаёт пустой объект
2. Устанавливает прототип
3. Вызывает конструктор с this = новый объект
4. Возвращает объект (если конструктор не вернул свой)

<b>С функцией-конструктором:</b>
<code>function User(name, age) {
  this.name = name;
  this.age = age;
}

const user = new User('John', 30);
console.log(user); // { name: 'John', age: 30 }
console.log(user instanceof User); // true</code>

<b>С классом:</b>
<code>class Person {
  constructor(name) {
    this.name = name;
  }
}

const person = new Person('Jane');</code>

<b>Что происходит внутри:</b>
<code>function User(name) {
  // this = {}; (неявно)
  // this.__proto__ = User.prototype;

  this.name = name;

  // return this; (неявно)
}

// Эквивалент new User('John')
const user = Object.create(User.prototype);
User.call(user, 'John');</code>

<b>⚠️ Без new:</b>
<code>function User(name) {
  this.name = name;
}

const user = User('John'); // ❌ this = window/undefined
console.log(user); // undefined
console.log(window.name); // 'John' (в браузере)</code>

<b>Защита от вызова без new:</b>
<code>function User(name) {
  if (!(this instanceof User)) {
    return new User(name);
  }
  this.name = name;
}</code>

💡 <b>Классы требуют new, иначе ошибка!</b>

🔀 <b>switch — множественный выбор</b>

<b>Базовый синтаксис:</b>
<code>const day = 2;

switch (day) {
  case 1:
    console.log('Понедельник');
    break;
  case 2:
    console.log('Вторник');
    break;
  default:
    console.log('Другой день');
}</code>

<b>⚠️ Проблема с переменными:</b>
<code>switch (value) {
  case 1:
    let x = 10; // ❌ SyntaxError
    break;
  case 2:
    let x = 20; // Конфликт!
    break;
}</code>

<b>✅ Решение — блоки:</b>
<code>switch (value) {
  case 1: {
    let x = 10; // ✅ Своя область видимости
    console.log(x);
    break;
  }
  case 2: {
    let x = 20; // ✅ Другая область
    console.log(x);
    break;
  }
}</code>

<b>Проваливание (fall-through):</b>
<code>switch (value) {
  case 1:
  case 2:
  case 3:
    console.log('1, 2 или 3');
    break;
  case 4:
    console.log('4');
    // Нет break — провалится в case 5!
  case 5:
    console.log('4 или 5');
    break;
}</code>

<b>Со строгим сравнением:</b>
<code>switch (value) {
  case '1': // Строгое сравнение (===)
    console.log('Строка 1');
    break;
  case 1:
    console.log('Число 1');
    break;
}</code>

💡 <b>Всегда используйте блоки для переменных в case!</b>

🎬 <b>requestAnimationFrame — плавная анимация</b>

<b>Что это:</b>
Метод для создания анимаций, синхронизированных с частотой обновления экрана (~60 FPS).

<b>Базовый пример:</b>
<code>function animate() {
  // Код анимации
  element.style.left = position + 'px';
  position += 1;

  // Запрос следующего кадра
  requestAnimationFrame(animate);
}

requestAnimationFrame(animate);</code>

<b>С остановкой:</b>
<code>let animationId;

function animate() {
  // Анимация
  position += 1;
  element.style.left = position + 'px';

  if (position < 500) {
    animationId = requestAnimationFrame(animate);
  }
}

animationId = requestAnimationFrame(animate);

// Остановка
cancelAnimationFrame(animationId);</code>

<b>Преимущества над setInterval:</b>
• Синхронизация с обновлением экрана
• Автоматическая пауза в неактивных вкладках
• Плавность 60 FPS
• Меньше нагрузка на CPU

<b>С временем:</b>
<code>let start;

function animate(timestamp) {
  if (!start) start = timestamp;
  const progress = timestamp - start;

  element.style.left = Math.min(progress / 10, 200) + 'px';

  if (progress < 2000) {
    requestAnimationFrame(animate);
  }
}

requestAnimationFrame(animate);</code>

<b>В React:</b>
<code>useEffect(() => {
  let animationId;

  const animate = () => {
    // Анимация
    animationId = requestAnimationFrame(animate);
  };

  animationId = requestAnimationFrame(animate);

  return () => cancelAnimationFrame(animationId);
}, []);</code>

💡 <b>Всегда используйте для анимаций вместо setInterval!</b>

👷 <b>Web Worker — фоновый поток для тяжёлых задач</b>

<b>Аналогия:</b>
Основной поток — официант в ресторане. Web Worker — повар на кухне. Официант не готовит сам, а передаёт заказ повару и продолжает обслуживать гостей.

<b>Зачем нужен:</b>
• JavaScript однопоточный
• Тяжёлые вычисления блокируют UI
• Worker выполняет задачи в фоне
• UI остаётся отзывчивым

<b>Создание Worker (worker.js):</b>
<code>// Слушаем сообщения от основного потока
self.onmessage = function(e) {
  const n = e.data;

  // Тяжёлое вычисление (Фибоначчи)
  const result = fibonacci(n);

  // Отправляем результат обратно
  self.postMessage(result);
};

function fibonacci(n) {
  if (n < 2) return n;
  return fibonacci(n - 1) + fibonacci(n - 2);
}</code>

<b>Использование (main.js):</b>
<code>// Создаём воркер
const worker = new Worker('worker.js');

// Отправляем данные
worker.postMessage(40);

// Получаем результат
worker.onmessage = function(e) {
  console.log('Результат:', e.data);
};

// Обработка ошибок
worker.onerror = function(e) {
  console.error('Ошибка:', e);
};

// Завершение работы
worker.terminate();</code>

<b>Кейсы использования:</b>
• Обработка больших данных (фильтрация, сортировка)
• Сложные вычисления (ML, криптография)
• Обработка изображений/видео
• Генерация отчётов
• Парсинг больших JSON

<b>⚠️ Ограничения:</b>
• Нет доступа к DOM
• Нет window, document
• Общение только через сообщения
• Есть Fetch, WebSockets, IndexedDB

💡 <b>Используйте для задач, которые блокируют UI!</b>

🔧 <b>Service Worker — прокси между приложением и сетью</b>

<b>Аналогия:</b>
Умный прокси-сервер в браузере, который перехватывает сетевые запросы и решает, что с ними делать.

<b>Зачем нужен:</b>
• Оффлайн-работа приложения (PWA)
• Кэширование ресурсов
• Push-уведомления
• Фоновая синхронизация
• Работает даже при закрытой вкладке

<b>Регистрация (main.js):</b>
<code>if ('serviceWorker' in navigator) {
  navigator.serviceWorker.register('/sw.js')
    .then(reg => console.log('SW registered'))
    .catch(err => console.error('SW failed', err));
}</code>

<b>Service Worker (sw.js):</b>
<code>// Установка — кэшируем файлы
self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open('app-v1').then(cache => {
      return cache.addAll([
        '/',
        '/styles.css',
        '/script.js',
        '/logo.png'
      ]);
    })
  );
});

// Перехват запросов
self.addEventListener('fetch', (event) => {
  event.respondWith(
    caches.match(event.request).then(response => {
      // Из кэша или из сети
      return response || fetch(event.request);
    })
  );
});</code>

<b>Push-уведомления:</b>
<code>self.addEventListener('push', (event) => {
  const options = {
    body: event.data.text(),
    icon: '/icon.png',
    badge: '/badge.png'
  };

  event.waitUntil(
    self.registration.showNotification('Новость!', options)
  );
});</code>

<b>Жизненный цикл:</b>
1. Installing — установка
2. Installed — установлен
3. Activating — активация
4. Activated — активен
5. Redundant — заменён новым

<b>Кейсы:</b>
• PWA с оффлайн-режимом
• Кэширование API-запросов
• Push-уведомления
• Фоновая загрузка данных

<b>⚠️ Требования:</b>
• Только HTTPS (кроме localhost)
• Асинхронный (промисы)
• Нет доступа к DOM

💡 <b>Основа Progressive Web Apps!</b>

🤝 <b>Shared Worker — общий воркер для нескольких вкладок</b>

<b>Аналогия:</b>
Общая комната для всех вкладок одного сайта. Web Worker — личная комната для одной вкладки.

<b>Зачем нужен:</b>
• Синхронизация между вкладками
• Общее состояние приложения
• Одно WebSocket-соединение на все вкладки
• Экономия ресурсов

<b>Shared Worker (shared-worker.js):</b>
<code>let connections = [];
let sharedData = { counter: 0 };

self.onconnect = function(event) {
  const port = event.ports[0];
  connections.push(port);

  // Отправляем текущее состояние
  port.postMessage({ type: 'INIT', data: sharedData });

  // Слушаем сообщения
  port.onmessage = function(e) {
    if (e.data.type === 'INCREMENT') {
      sharedData.counter++;

      // Рассылаем всем вкладкам
      connections.forEach(conn => {
        conn.postMessage({ type: 'UPDATE', data: sharedData });
      });
    }
  };

  port.start();
};</code>

<b>Использование (main.js):</b>
<code>// Создаём Shared Worker
const worker = new SharedWorker('shared-worker.js');

// Получаем порт
worker.port.start();

// Слушаем сообщения
worker.port.onmessage = function(e) {
  if (e.data.type === 'UPDATE' || e.data.type === 'INIT') {
    document.getElementById('counter').textContent = e.data.data.counter;
  }
};

// Отправляем сообщение
document.getElementById('btn').onclick = () => {
  worker.port.postMessage({ type: 'INCREMENT' });
};</code>

<b>Кейсы использования:</b>
• Синхронизация счётчика между вкладками
• Общий музыкальный плеер
• Одно WebSocket-соединение для всех вкладок
• Синхронизация корзины покупок
• Общий кэш данных

<b>Сравнение воркеров:</b>
• <b>Web Worker:</b> Одна вкладка, тяжёлые вычисления
• <b>Service Worker:</b> Все вкладки, сетевой прокси, PWA
• <b>Shared Worker:</b> Несколько вкладок, общее состояние

<b>⚠️ Особенности:</b>
• Один воркер на все вкладки домена
• Общение через порты (MessagePort)
• Автоматически уничтожается при закрытии всех вкладок
• Меньшая поддержка браузерами

💡 <b>Идеален для синхронизации между вкладками!</b>

react.answer:
React JS, или просто React, это открытая библиотека JavaScript для создания пользовательских интерфейсов, особенно для одностраничных приложений (SPA). Ключевые особенности React:
1) Компонентный подход: React строится на концепции компонентов, что позволяет разработчикам создавать легко переиспользуемые куски кода;
2) Виртуальный DOM: React использует виртуальный DOM для отслеживания изменений. Это абстракция реального DOM, что позволяет библиотеке обновлять только те части интерфейса, которые действительно изменились, вместо полного перерендеринга страницы. Это делает React относительно быстрым;
3) Хуки: Введение хуков позволило использовать состояния и другие возможности классовых компонентов в функциональных компонентах, что сделало код более кратким и чистым;
4) Сообщество и экосистема: React имеет большое и активное сообщество разработчиков, а также много библиотек и инструментов, созданных сообществом, что облегчает разработку сложных приложений.

Подробнее: <a href='https://youtu.be/R_39q-vdOaE?si=mEKDaYDjEdnojG-N' target='_blank'>Введение в React (видео)</a>

📦 <b>Изменение state — главный триггер рендеринга!</b>

<b>Пример с useState:</b>
<code>function Counter() {
  const [count, setCount] = useState(0);

  const increment = () => {
    setCount(count + 1); // ✅ Вызывает рендеринг
  };

  return (
    &lt;div&gt;
      &lt;p&gt;Счёт: {count}&lt;/p&gt;
      &lt;button onClick={increment}&gt;+1&lt;/button&gt;
    &lt;/div&gt;
  );
}</code>

🔍 <b>Что происходит:</b>
1. При клике вызывается setCount(1)
2. React планирует рендеринг компонента
3. Компонент перерисовывается с новым count
4. React обновляет DOM

⚠️ <b>Важно:</b> setState асинхронный! Состояние обновится не сразу.

🎯 <b>Props — это данные от родителя к ребёнку</b>

<b>Пример:</b>
<code>// Родитель
function Parent() {
  const [name, setName] = useState('Иван');
  return &lt;Child name={name} /&gt;; // ✅ Передаём проп
}

// Ребёнок
function Child({ name }) {
  console.log('Child рендерится!');
  return &lt;p&gt;Привет, {name}!&lt;/p&gt;
}</code>

🔄 <b>Что происходит:</b>
1. Parent меняет state (name)
2. Parent перерисовывается
3. Child получает новый проп name
4. Child перерисовывается с новым значением

💡 <b>Оптимизация:</b> Используйте React.memo, чтобы Child не рендерился, если пропсы не изменились:
<code>const Child = React.memo(({ name }) => {
  return &lt;p&gt;Привет, {name}!&lt;/p&gt;
});</code>

🌊 <b>Context — это глобальное состояние для дерева компонентов</b>

<b>Пример:</b>
<code>const ThemeContext = createContext();

function App() {
  const [theme, setTheme] = useState('light');
  return (
    &lt;ThemeContext.Provider value={theme}&gt;
      &lt;Header /&gt;
      &lt;Content /&gt; {/* Использует контекст */}
    &lt;/ThemeContext.Provider&gt;
  );
}

function Content() {
  const theme = useContext(ThemeContext);
  return &lt;div&gt;Тема: {theme}&lt;/div&gt;;
}</code>

🔄 <b>Каскадный эффект:</b>
Когда Provider обновляется (theme меняется), ВСЕ компоненты, использующие useContext(ThemeContext), перерисовываются — даже если они глубоко вложены!

⚠️ <b>Проблема:</b> Если много компонентов используют контекст, все они перерисуются.

💡 <b>Решение:</b> Разделяйте контексты или используйте useMemo для значений Provider.

⚡ <b>forceUpdate() — принудительный рендеринг</b>

<b>Пример:</b>
<code>class MyComponent extends React.Component {
  handleClick = () => {
    // Изменяем данные напрямую (плохая практика!)
    this.data = { value: Math.random() };
    this.forceUpdate(); // ⚠️ Принудительный рендер
  };

  render() {
    return &lt;button onClick={this.handleClick}&gt;Обновить&lt;/button&gt;
  }
}</code>

❌ <b>Когда НЕ использовать:</b>
- Почти всегда! Это антипаттерн
- Если можно использовать setState

✅ <b>Редкие случаи использования:</b>
- Интеграция со сторонними библиотеками
- Работа с внешними данными вне React

💡 <b>Лучше:</b> Используйте state или props. В функциональных компонентах forceUpdate нет — используйте useState с фиктивным обновлением:
<code>const [, forceUpdate] = useReducer(x => x + 1, 0);</code>

🔑 <b>Key — это идентификатор элемента для React</b>

<b>Пример:</b>
<code>function UserProfile({ userId }) {
  const [data, setData] = useState(null);

  useEffect(() => {
    fetchUser(userId).then(setData);
  }, [userId]);

  return &lt;div&gt;{data?.name}&lt;/div&gt;
}

// Использование с key
&lt;UserProfile key={userId} userId={userId} /&gt;</code>

🔄 <b>Что происходит при изменении key:</b>
1. React считает это НОВЫМ компонентом
2. Старый компонент размонтируется (unmount)
3. Новый компонент монтируется (mount)
4. State полностью сбрасывается!

💡 <b>Когда использовать:</b>
- Сброс формы при смене пользователя
- Сброс анимации
- Принудительный ремонтаж компонента

⚠️ <b>Важно:</b> Не используйте индексы массива как key в динамических списках!

🧪 <b>Чистая vs Нечистая функция</b>

<b>❌ Нечистая функция (плохо):</b>
<code>let counter = 0;

function ImpureComponent() {
  counter++; // ⚠️ Побочный эффект!
  return &lt;div&gt;Рендер #{counter}&lt;/div&gt;
}</code>

<b>✅ Чистая функция (хорошо):</b>
<code>function PureComponent({ count }) {
  return &lt;div&gt;Рендер #{count}&lt;/div&gt;
}</code>

🔍 <b>Проблемы нечистых функций:</b>
1. Непредсказуемое поведение
2. Сложно отлаживать
3. React может рендерить компонент дважды в Strict Mode
4. Проблемы с мемоизацией (React.memo не работает)

💡 <b>Правило:</b> Компонент должен быть чистой функцией:
- Одинаковые props → одинаковый результат
- Без побочных эффектов в render
- Побочные эффекты только в useEffect/обработчиках событий

👨‍👧 <b>Родитель рендерится → дети рендерятся</b>

<b>Пример:</b>
<code>function Parent() {
  const [count, setCount] = useState(0);
  console.log('Parent render');

  return (
    &lt;div&gt;
      &lt;button onClick={() => setCount(count + 1)}&gt;{count}&lt;/button&gt;
      &lt;Child /&gt; {/* ⚠️ Перерисуется, даже без пропсов! */}
    &lt;/div&gt;
  );
}

function Child() {
  console.log('Child render'); // Вызовется при каждом клике!
  return &lt;p&gt;Я дочерний компонент&lt;/p&gt;
}</code>

🔄 <b>Что происходит:</b>
1. Клик → Parent обновляет state
2. Parent рендерится
3. Child рендерится автоматически (даже если пропсы не изменились!)

💡 <b>Оптимизация с React.memo:</b>
<code>const Child = React.memo(() => {
  console.log('Child render'); // Теперь не вызовется!
  return &lt;p&gt;Я дочерний компонент&lt;/p&gt;
});</code>

✅ Теперь Child рендерится только при изменении пропсов!

⏱️ <b>useEffect сам по себе НЕ вызывает рендеринг</b>

<b>Пример:</b>
<code>function UserData({ userId }) {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    setLoading(true); // ✅ Рендеринг #1

    fetch(`/api/users/${userId}`)
      .then(res => res.json())
      .then(data => {
        setUser(data);      // ✅ Рендеринг #2
        setLoading(false);  // ✅ Рендеринг #3
      });
  }, [userId]);

  if (loading) return &lt;div&gt;Загрузка...&lt;/div&gt;
  return &lt;div&gt;{user.name}&lt;/div&gt;
}</code>

🔄 <b>Цепочка рендеров:</b>
1. Компонент монтируется → useEffect запускается
2. setLoading(true) → рендеринг
3. Fetch завершается → setUser(data) → рендеринг
4. setLoading(false) → рендеринг

💡 <b>Оптимизация:</b>
<code>setUser(data);
setLoading(false);
// React 18 автоматически батчит оба обновления в один рендер!</code>

🔍 <b>Strict Mode — режим строгой проверки</b>

<b>Использование:</b>
<code>&lt;React.StrictMode&gt;
  &lt;App /&gt;
&lt;/React.StrictMode&gt;</code>

🎯 <b>Что делает Strict Mode:</b>
1. ⚠️ Рендерит компоненты ДВАЖДЫ (только в dev режиме!)
2. Проверяет устаревшие методы жизненного цикла
3. Предупреждает о небезопасных побочных эффектах
4. Проверяет устаревшие API

<b>Пример двойного рендера:</b>
<code>function MyComponent() {
  console.log('Render'); // Выведется 2 раза в dev!
  return &lt;div&gt;Hello&lt;/div&gt;
}</code>

💡 <b>Зачем двойной рендер?</b>
Помогает найти нечистые функции и побочные эффекты:
<code>// ❌ Плохо — будет видно в Strict Mode
let count = 0;
function Bad() {
  count++; // Побочный эффект!
  return &lt;div&gt;{count}&lt;/div&gt;
}</code>

✅ <b>В production:</b> Strict Mode не влияет на производительность!

🛡️ <b>Error Boundary — ловушка для ошибок рендеринга</b>

<b>Пример:</b>
<code>class ErrorBoundary extends React.Component {
  state = { hasError: false };

  static getDerivedStateFromError(error) {
    return { hasError: true }; // ✅ Обновляет state → рендеринг
  }

  componentDidCatch(error, info) {
    console.error('Ошибка:', error, info);
  }

  render() {
    if (this.state.hasError) {
      return &lt;h1&gt;Что-то пошло не так 😢&lt;/h1&gt;
    }
    return this.props.children;
  }
}

// Использование
&lt;ErrorBoundary&gt;
  &lt;MyComponent /&gt;
&lt;/ErrorBoundary&gt;</code>

🔄 <b>Что происходит при ошибке:</b>
1. MyComponent выбрасывает ошибку
2. getDerivedStateFromError обновляет state
3. ErrorBoundary рендерится с запасным UI
4. Дочерние компоненты не рендерятся

⚠️ <b>Не ловит:</b> Ошибки в обработчиках событий, async коде, SSR

🚀 <b>React.memo — мемоизация компонента</b>

<b>Без оптимизации:</b>
<code>function ExpensiveChild({ data }) {
  console.log('Рендер!'); // Вызывается при каждом рендере родителя
  return &lt;div&gt;{data}&lt;/div&gt;
}</code>

<b>✅ С React.memo:</b>
<code>const ExpensiveChild = React.memo(({ data }) => {
  console.log('Рендер!'); // Вызывается только при изменении data
  return &lt;div&gt;{data}&lt;/div&gt;
});</code>

🎯 <b>Когда использовать:</b>
1. Компонент рендерится часто с одинаковыми пропсами
2. Компонент тяжёлый (много вычислений)
3. Компонент в списке

❌ <b>Когда НЕ использовать:</b>
1. Пропсы меняются при каждом рендере
2. Компонент лёгкий
3. Преждевременная оптимизация

💡 <b>Кастомное сравнение:</b>
<code>const Child = React.memo(Component, (prevProps, nextProps) => {
  return prevProps.id === nextProps.id; // true = не рендерить
});</code>

🔄 <b>useMemo vs useCallback</b>

<b>useMemo — мемоизирует ЗНАЧЕНИЕ:</b>
<code>function Component({ items }) {
  // ✅ Вычисляется только при изменении items
  const total = useMemo(() => {
    return items.reduce((sum, item) => sum + item.price, 0);
  }, [items]);

  return &lt;div&gt;Итого: {total}&lt;/div&gt;
}</code>

<b>useCallback — мемоизирует ФУНКЦИЮ:</b>
<code>function Parent() {
  const [count, setCount] = useState(0);

  // ✅ Функция создаётся один раз
  const handleClick = useCallback(() => {
    console.log('Клик!');
  }, []); // Без зависимостей

  return &lt;Child onClick={handleClick} /&gt;
}</code>

📊 <b>Сравнение:</b>
• useMemo(() => value, deps) → возвращает value
• useCallback(fn, deps) → возвращает fn
• useCallback(fn, deps) === useMemo(() => fn, deps)

💡 <b>Когда использовать:</b>
• useMemo: тяжёлые вычисления, объекты/массивы для пропсов
• useCallback: функции для пропсов мемоизированных компонентов

🎛️ <b>useReducer — для сложного состояния</b>

<b>useState (простое состояние):</b>
<code>const [count, setCount] = useState(0);
setCount(count + 1);</code>

<b>useReducer (сложная логика):</b>
<code>const initialState = { count: 0, history: [] };

function reducer(state, action) {
  switch (action.type) {
    case 'increment':
      return {
        count: state.count + 1,
        history: [...state.history, state.count]
      };
    case 'decrement':
      return {
        count: state.count - 1,
        history: [...state.history, state.count]
      };
    default:
      return state;
  }
}

const [state, dispatch] = useReducer(reducer, initialState);
dispatch({ type: 'increment' });</code>

✅ <b>Используйте useReducer когда:</b>
1. Состояние — сложный объект
2. Много связанных обновлений
3. Следующее состояние зависит от предыдущего
4. Логика обновления сложная

💡 <b>Используйте useState когда:</b>
Простое значение (число, строка, boolean)

⏳ <b>Ленивая загрузка — загрузка по требованию</b>

<b>Без ленивой загрузки:</b>
<code>import HeavyComponent from './HeavyComponent';
// ❌ Загружается сразу, увеличивает bundle</code>

<b>✅ С React.lazy:</b>
<code>import { lazy, Suspense } from 'react';

const HeavyComponent = lazy(() => import('./HeavyComponent'));

function App() {
  return (
    &lt;Suspense fallback={&lt;div&gt;Загрузка...&lt;/div&gt;}&gt;
      &lt;HeavyComponent /&gt;
    &lt;/Suspense&gt;
  );
}</code>

🎯 <b>Как работает:</b>
1. HeavyComponent не загружается при старте
2. Загружается только когда рендерится
3. Пока загружается — показывается fallback
4. После загрузки — показывается компонент

💡 <b>Когда использовать:</b>
• Большие компоненты (графики, редакторы)
• Модальные окна
• Роуты в React Router

<b>Пример с роутами:</b>
<code>const Home = lazy(() => import('./pages/Home'));
const About = lazy(() => import('./pages/About'));</code>

🎯 <b>Правила зависимостей в useEffect</b>

<b>❌ Плохо — пропущена зависимость:</b>
<code>useEffect(() => {
  console.log(count); // count не в зависимостях!
}, []); // ⚠️ Устаревшее значение</code>

<b>✅ Хорошо — все зависимости указаны:</b>
<code>useEffect(() => {
  console.log(count);
}, [count]); // ✅ Обновится при изменении count</code>

<b>Функции в зависимостях:</b>
<code>// ❌ Плохо
const fetchData = () => fetch('/api');
useEffect(() => {
  fetchData();
}, [fetchData]); // Бесконечный цикл!

// ✅ Хорошо
const fetchData = useCallback(() => fetch('/api'), []);
useEffect(() => {
  fetchData();
}, [fetchData]);</code>

💡 <b>Правила:</b>
1. Указывайте ВСЕ используемые переменные из внешней области
2. Используйте useCallback для функций
3. Используйте useMemo для объектов/массивов
4. Пустой [] = выполнится один раз при монтировании

🎨 <b>PureComponent — оптимизированный компонент</b>

<b>Обычный Component:</b>
<code>class Regular extends React.Component {
  render() {
    return &lt;div&gt;{this.props.name}&lt;/div&gt;
  }
  // Рендерится при каждом обновлении родителя
}</code>

<b>✅ PureComponent:</b>
<code>class Pure extends React.PureComponent {
  render() {
    return &lt;div&gt;{this.props.name}&lt;/div&gt;
  }
  // Рендерится только если props/state изменились
}</code>

🔍 <b>Как работает:</b>
PureComponent автоматически реализует shouldComponentUpdate с поверхностным сравнением (shallow comparison) props и state.

<b>Поверхностное сравнение:</b>
<code>// Примитивы — сравниваются по значению
oldProps.count === newProps.count // 1 === 1 → true

// Объекты — сравниваются по ссылке
oldProps.user === newProps.user // {...} === {...} → false</code>

💡 <b>Аналог в функциональных компонентах:</b> React.memo

⚖️ <b>Поверхностное vs Глубокое сравнение</b>

<b>Поверхностное (shallow):</b>
<code>const obj1 = { name: 'Иван', age: 30 };
const obj2 = { name: 'Иван', age: 30 };
obj1 === obj2 // false (разные ссылки!)</code>

<b>Глубокое (deep):</b>
<code>_.isEqual(obj1, obj2) // true (одинаковое содержимое)</code>

❌ <b>Проблема с PureComponent:</b>
<code>class List extends React.PureComponent {
  render() {
    return &lt;ul&gt;{this.props.items.map(...)}&lt;/ul&gt;
  }
}

// В родителе
this.state.items.push(newItem); // ⚠️ Мутация!
this.setState({ items: this.state.items }); // Та же ссылка!
// List НЕ перерисуется!</code>

✅ <b>Правильно — иммутабельность:</b>
<code>this.setState({
  items: [...this.state.items, newItem] // Новая ссылка
});</code>

💡 <b>Почему поверхностное?</b>
Глубокое сравнение медленное для больших объектов. Поверхностное — быстрое, но требует иммутабельности.

🎛️ <b>shouldComponentUpdate — ручная оптимизация</b>

<b>Без оптимизации:</b>
<code>class MyComponent extends React.Component {
  render() {
    console.log('Render!'); // Вызывается всегда
    return &lt;div&gt;{this.props.value}&lt;/div&gt;
  }
}</code>

<b>✅ С shouldComponentUpdate:</b>
<code>class MyComponent extends React.Component {
  shouldComponentUpdate(nextProps, nextState) {
    // Рендерить только если value изменился
    return nextProps.value !== this.props.value;
  }

  render() {
    console.log('Render!'); // Вызывается только при изменении value
    return &lt;div&gt;{this.props.value}&lt;/div&gt;
  }
}</code>

🔍 <b>Как работает:</b>
- Возвращает true → компонент рендерится
- Возвращает false → рендеринг пропускается

💡 <b>Когда использовать:</b>
- Сложная логика сравнения
- Оптимизация тяжёлых компонентов
- Когда PureComponent недостаточно

⚠️ <b>В функциональных компонентах:</b> Используйте React.memo с кастомным компаратором

✨ <b>Чистый компонент = Предсказуемый компонент</b>

<b>Определение:</b>
Чистый компонент — это компонент, который при одинаковых props всегда возвращает одинаковый результат, без побочных эффектов.

<b>✅ Чистый компонент:</b>
<code>function PureGreeting({ name }) {
  return &lt;h1&gt;Привет, {name}!&lt;/h1&gt;
}
// name='Иван' → всегда 'Привет, Иван!'</code>

<b>❌ Нечистый компонент:</b>
<code>let counter = 0;
function ImpureGreeting({ name }) {
  counter++; // Побочный эффект!
  return &lt;h1&gt;Привет, {name}! (#{counter})&lt;/h1&gt;
}
// name='Иван' → разный результат каждый раз!</code>

🎯 <b>Преимущества чистых компонентов:</b>
1. Легко тестировать
2. Легко отлаживать
3. Можно мемоизировать (React.memo)
4. Предсказуемое поведение
5. Работают с Concurrent Mode

💡 <b>Правило:</b> Побочные эффекты только в useEffect и обработчиках событий!

🔑 <b>Key помогает React идентифицировать элементы</b>

<b>❌ Без key:</b>
<code>function TodoList({ todos }) {
  return (
    &lt;ul&gt;
      {todos.map(todo => (
        &lt;li&gt;{todo.text}&lt;/li&gt; {/* ⚠️ Нет key! */}
      ))}
    &lt;/ul&gt;
  );
}</code>

<b>Проблема:</b>
<code>// Было: ['A', 'B', 'C']
// Стало: ['X', 'A', 'B', 'C']
// React думает:
// 'A' изменился на 'X' → обновить
// 'B' изменился на 'A' → обновить
// 'C' изменился на 'B' → обновить
// Добавить 'C' → создать
// ⚠️ 4 операции вместо 1!</code>

<b>✅ С key:</b>
<code>function TodoList({ todos }) {
  return (
    &lt;ul&gt;
      {todos.map(todo => (
        &lt;li key={todo.id}&gt;{todo.text}&lt;/li&gt;
      ))}
    &lt;/ul&gt;
  );
}
// React видит: добавлен новый элемент с key='X'
// ✅ 1 операция!</code>

💡 <b>Проблемы без key:</b>
- Неправильный порядок
- Потеря состояния (input значения)
- Плохая производительность

📋 <b>Правила использования key</b>

<b>✅ Хорошие key:</b>
<code>// 1. Уникальный ID из базы данных
{users.map(user => (
  &lt;User key={user.id} data={user} /&gt;
))}

// 2. Уникальный идентификатор
{items.map(item => (
  &lt;Item key={item.sku} data={item} /&gt;
))}</code>

<b>⚠️ Индексы (осторожно!):</b>
<code>// ✅ OK — статичный список, не меняется
const COLORS = ['red', 'green', 'blue'];
{COLORS.map((color, index) => (
  &lt;div key={index}&gt;{color}&lt;/div&gt;
))}

// ❌ ПЛОХО — динамический список
{todos.map((todo, index) => (
  &lt;Todo key={index} data={todo} /&gt; {/* Проблемы при удалении/добавлении */}
))}</code>

<b>Проблема с индексами:</b>
<code>// Было: [A(0), B(1), C(2)]
// Удалили A
// Стало: [B(0), C(1)]
// React думает: B изменился, C изменился
// ⚠️ Потеря состояния!</code>

💡 <b>Правила:</b>
1. Key должен быть уникальным среди соседей
2. Key должен быть стабильным (не меняться)
3. Не используйте Math.random()

🌐 <b>useEffect + Fetch = Загрузка данных</b>

<b>✅ Правильный способ:</b>
<code>function UserProfile({ userId }) {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    let cancelled = false; // Флаг отмены

    setLoading(true);
    fetch(`/api/users/${userId}`)
      .then(res => res.json())
      .then(data => {
        if (!cancelled) { // Проверка отмены
          setUser(data);
          setLoading(false);
        }
      })
      .catch(err => {
        if (!cancelled) {
          setError(err);
          setLoading(false);
        }
      });

    return () => {
      cancelled = true; // Отменяем при размонтировании
    };
  }, [userId]);

  if (loading) return &lt;div&gt;Загрузка...&lt;/div&gt;
  if (error) return &lt;div&gt;Ошибка: {error.message}&lt;/div&gt;
  return &lt;div&gt;{user.name}&lt;/div&gt;
}</code>

⚠️ <b>Важно:</b> Cleanup функция предотвращает обновление размонтированного компонента!

🏁 <b>Race Condition — когда запросы приходят не по порядку</b>

<b>❌ Проблема:</b>
<code>// Пользователь быстро переключается: user1 → user2 → user3
// Запросы: req1, req2, req3
// Ответы приходят: res3, res1, res2
// Показывается user2 вместо user3! ⚠️</code>

<b>✅ Решение 1 — Флаг отмены:</b>
<code>useEffect(() => {
  let active = true;

  fetch(`/api/users/${userId}`)
    .then(res => res.json())
    .then(data => {
      if (active) { // Игнорируем устаревшие ответы
        setUser(data);
      }
    });

  return () => { active = false; };
}, [userId]);</code>

<b>✅ Решение 2 — AbortController:</b>
<code>useEffect(() => {
  const controller = new AbortController();

  fetch(`/api/users/${userId}`, {
    signal: controller.signal
  })
    .then(res => res.json())
    .then(setUser)
    .catch(err => {
      if (err.name !== 'AbortError') {
        console.error(err);
      }
    });

  return () => controller.abort(); // Отменяем запрос
}, [userId]);</code>

🔄 <b>Reconciliation — процесс сверки и обновления DOM</b>

<b>Как работает:</b>
1. React создаёт новое виртуальное дерево (Virtual DOM)
2. Сравнивает с предыдущим деревом (Diffing)
3. Вычисляет минимальные изменения
4. Обновляет только изменённые части реального DOM

<b>Алгоритм сравнения:</b>
<code>// 1. Разные типы элементов → полная замена
&lt;div&gt; → &lt;span&gt; // Удалить div, создать span

// 2. Одинаковые типы → обновить атрибуты
&lt;div className="old"&gt; → &lt;div className="new"&gt;
// Обновить только className

// 3. Дочерние элементы → сравнить по порядку
&lt;ul&gt;
  &lt;li&gt;A&lt;/li&gt;
  &lt;li&gt;B&lt;/li&gt;
&lt;/ul&gt;
→
&lt;ul&gt;
  &lt;li&gt;A&lt;/li&gt;
  &lt;li&gt;B&lt;/li&gt;
  &lt;li&gt;C&lt;/li&gt; {/* Добавить */}
&lt;/ul&gt;</code>

💡 <b>Оптимизация:</b> Используйте key для списков, чтобы React мог эффективно определять изменения!

🎯 <b>Результат:</b> Быстрые обновления UI без полной перерисовки страницы

🔑 <b>Keys помогают React отслеживать элементы</b>

<b>Без key (медленно):</b>
<code>// Было:
&lt;ul&gt;
  &lt;li&gt;A&lt;/li&gt;
  &lt;li&gt;B&lt;/li&gt;
&lt;/ul&gt;

// Добавили в начало:
&lt;ul&gt;
  &lt;li&gt;Z&lt;/li&gt;
  &lt;li&gt;A&lt;/li&gt;
  &lt;li&gt;B&lt;/li&gt;
&lt;/ul&gt;

// React думает:
// Позиция 0: A → Z (обновить)
// Позиция 1: B → A (обновить)
// Позиция 2: нет → B (создать)
// ⚠️ 3 операции!</code>

<b>С key (быстро):</b>
<code>// Было:
&lt;ul&gt;
  &lt;li key="a"&gt;A&lt;/li&gt;
  &lt;li key="b"&gt;B&lt;/li&gt;
&lt;/ul&gt;

// Добавили:
&lt;ul&gt;
  &lt;li key="z"&gt;Z&lt;/li&gt;
  &lt;li key="a"&gt;A&lt;/li&gt;
  &lt;li key="b"&gt;B&lt;/li&gt;
&lt;/ul&gt;

// React видит:
// key="z" — новый элемент (создать)
// key="a" — существует (переместить)
// key="b" — существует (переместить)
// ✅ 1 операция создания, 2 перемещения (быстро!)</code>

💡 <b>Вывод:</b> Keys позволяют React понять, какие элементы изменились, добавились или удалились

🌐 <b>Context — глобальное состояние без prop drilling</b>

<b>Проблема без Context (prop drilling):</b>
<code>function App() {
  const user = { name: 'Иван' };
  return &lt;Level1 user={user} /&gt;;
}

function Level1({ user }) {
  return &lt;Level2 user={user} /&gt;; // Пробрасываем
}

function Level2({ user }) {
  return &lt;Level3 user={user} /&gt;; // Пробрасываем
}

function Level3({ user }) {
  return &lt;div&gt;{user.name}&lt;/div&gt;; // Наконец используем!
}</code>

<b>✅ Решение с Context:</b>
<code>const UserContext = createContext();

function App() {
  const user = { name: 'Иван' };
  return (
    &lt;UserContext.Provider value={user}&gt;
      &lt;Level1 /&gt;
    &lt;/UserContext.Provider&gt;
  );
}

function Level3() {
  const user = useContext(UserContext); // Прямой доступ!
  return &lt;div&gt;{user.name}&lt;/div&gt;
}</code>

🎯 <b>Когда использовать:</b>
• Тема (светлая/тёмная)
• Язык интерфейса
• Данные авторизации
• Настройки приложения

⚠️ <b>Не используйте для:</b> Часто меняющихся данных (используйте state management)

📦 <b>Полный пример Context</b>

<b>1. Создание Context:</b>
<code>import { createContext, useState, useContext } from 'react';

const ThemeContext = createContext();</code>

<b>2. Provider компонент:</b>
<code>function ThemeProvider({ children }) {
  const [theme, setTheme] = useState('light');

  const toggleTheme = () => {
    setTheme(prev => prev === 'light' ? 'dark' : 'light');
  };

  return (
    &lt;ThemeContext.Provider value={{ theme, toggleTheme }}&gt;
      {children}
    &lt;/ThemeContext.Provider&gt;
  );
}</code>

<b>3. Кастомный хук (опционально):</b>
<code>function useTheme() {
  const context = useContext(ThemeContext);
  if (!context) {
    throw new Error('useTheme must be used within ThemeProvider');
  }
  return context;
}</code>

<b>4. Использование:</b>
<code>function App() {
  return (
    &lt;ThemeProvider&gt;
      &lt;Header /&gt;
      &lt;Content /&gt;
    &lt;/ThemeProvider&gt;
  );
}

function Header() {
  const { theme, toggleTheme } = useTheme();
  return (
    &lt;header className={theme}&gt;
      &lt;button onClick={toggleTheme}&gt;Сменить тему&lt;/button&gt;
    &lt;/header&gt;
  );
}</code>

📦 <b>Fragment — группировка без лишних DOM узлов</b>

<b>❌ Проблема с div:</b>
<code>function Table() {
  return (
    &lt;table&gt;
      &lt;tbody&gt;
        &lt;TableRow /&gt;
      &lt;/tbody&gt;
    &lt;/table&gt;
  );
}

function TableRow() {
  return (
    &lt;div&gt; {/* ⚠️ Невалидный HTML! */}
      &lt;td&gt;Ячейка 1&lt;/td&gt;
      &lt;td&gt;Ячейка 2&lt;/td&gt;
    &lt;/div&gt;
  );
}</code>

<b>✅ Решение с Fragment:</b>
<code>function TableRow() {
  return (
    &lt;React.Fragment&gt;
      &lt;td&gt;Ячейка 1&lt;/td&gt;
      &lt;td&gt;Ячейка 2&lt;/td&gt;
    &lt;/React.Fragment&gt;
  );
}

// Короткий синтаксис:
function TableRow() {
  return (
    &lt;&gt;
      &lt;td&gt;Ячейка 1&lt;/td&gt;
      &lt;td&gt;Ячейка 2&lt;/td&gt;
    &lt;/&gt;
  );
}</code>

🎯 <b>Преимущества:</b>
• Не создаёт лишние DOM узлы
• Валидный HTML
• Чище инспектор браузера
• Лучше производительность

💡 <b>С key:</b>
<code>&lt;React.Fragment key={item.id}&gt;...&lt;/React.Fragment&gt;</code>

🪝 <b>Хуки — функции для работы с состоянием и эффектами</b>

<b>До хуков (классы):</b>
<code>class Counter extends React.Component {
  state = { count: 0 };

  componentDidMount() {
    document.title = `Счёт: ${this.state.count}`;
  }

  componentDidUpdate() {
    document.title = `Счёт: ${this.state.count}`;
  }

  render() {
    return (
      &lt;button onClick={() => this.setState({ count: this.state.count + 1 })}&gt;
        {this.state.count}
      &lt;/button&gt;
    );
  }
}</code>

<b>✅ С хуками (функции):</b>
<code>function Counter() {
  const [count, setCount] = useState(0);

  useEffect(() => {
    document.title = `Счёт: ${count}`;
  }, [count]);

  return &lt;button onClick={() => setCount(count + 1)}&gt;{count}&lt;/button&gt;
}</code>

🎯 <b>Преимущества хуков:</b>
1. Меньше кода
2. Легче переиспользовать логику (кастомные хуки)
3. Нет проблем с this
4. Легче тестировать
5. Лучше композиция

🔢 <b>useState — хук для состояния</b>

<b>Базовый пример:</b>
<code>function Counter() {
  // [текущее значение, функция обновления]
  const [count, setCount] = useState(0); // 0 — начальное значение

  return (
    &lt;div&gt;
      &lt;p&gt;Счёт: {count}&lt;/p&gt;
      &lt;button onClick={() => setCount(count + 1)}&gt;+1&lt;/button&gt;
      &lt;button onClick={() => setCount(count - 1)}&gt;-1&lt;/button&gt;
      &lt;button onClick={() => setCount(0)}&gt;Сброс&lt;/button&gt;
    &lt;/div&gt;
  );
}</code>

<b>Функциональное обновление:</b>
<code>// ❌ Плохо — может быть устаревшее значение
setCount(count + 1);

// ✅ Хорошо — всегда актуальное значение
setCount(prevCount => prevCount + 1);</code>

<b>Множественные клики:</b>
<code>function handleClick() {
  setCount(count + 1); // count = 0 → 1
  setCount(count + 1); // count = 0 → 1 (устаревшее!)
  // Результат: 1 ⚠️

  // Правильно:
  setCount(c => c + 1); // 0 → 1
  setCount(c => c + 1); // 1 → 2
  // Результат: 2 ✅
}</code>

⚡ <b>useEffect — хук для побочных эффектов</b>

<b>Пример загрузки данных:</b>
<code>function UserProfile({ userId }) {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Эффект выполняется после рендера
    setLoading(true);

    fetch(`/api/users/${userId}`)
      .then(res => res.json())
      .then(data => {
        setUser(data);
        setLoading(false);
      });

    // Cleanup функция (опционально)
    return () => {
      console.log('Компонент размонтируется');
    };
  }, [userId]); // Зависимости — перезапуск при изменении userId

  if (loading) return &lt;div&gt;Загрузка...&lt;/div&gt;
  return &lt;div&gt;{user.name}&lt;/div&gt;
}</code>

📋 <b>Варианты зависимостей:</b>
<code>useEffect(() => {}, []); // Один раз при монтировании
useEffect(() => {}, [a, b]); // При изменении a или b
useEffect(() => {}); // После каждого рендера</code>

💡 <b>Когда использовать:</b> Fetch, подписки, таймеры, изменение DOM, логирование

🌐 <b>useContext — доступ к контексту</b>

<b>❌ Проблема (prop drilling):</b>
<code>function App() {
  const theme = 'dark';
  return &lt;Parent theme={theme} /&gt;;
}

function Parent({ theme }) {
  return &lt;Child theme={theme} /&gt;; // Пробрасываем
}

function Child({ theme }) {
  return &lt;GrandChild theme={theme} /&gt;; // Пробрасываем
}

function GrandChild({ theme }) {
  return &lt;div className={theme}&gt;Контент&lt;/div&gt;
}</code>

<b>✅ Решение с useContext:</b>
<code>const ThemeContext = createContext();

function App() {
  const theme = 'dark';
  return (
    &lt;ThemeContext.Provider value={theme}&gt;
      &lt;Parent /&gt; {/* Не нужны пропсы! */}
    &lt;/ThemeContext.Provider&gt;
  );
}

function GrandChild() {
  const theme = useContext(ThemeContext); // Прямой доступ!
  return &lt;div className={theme}&gt;Контент&lt;/div&gt;
}</code>

💡 <b>Преимущества:</b>
• Нет промежуточных пропсов
• Легче рефакторинг
• Чище код

🎯 <b>useRef — ссылка на DOM элемент</b>

<b>Пример — фокус на input:</b>
<code>function SearchInput() {
  const inputRef = useRef(null);

  const handleClick = () => {
    inputRef.current.focus(); // Фокус на input
  };

  return (
    &lt;div&gt;
      &lt;input ref={inputRef} type="text" /&gt;
      &lt;button onClick={handleClick}&gt;Фокус&lt;/button&gt;
    &lt;/div&gt;
  );
}</code>

<b>Пример — скролл к элементу:</b>
<code>function ScrollToTop() {
  const topRef = useRef(null);

