• Хранения мутабельных значений
• Предыдущих значений

📝 <b>useReducer для TODO-листа</b>

<code>function todoReducer(state, action) {
  switch (action.type) {
    case 'ADD':
      return [...state, { id: Date.now(), text: action.text, done: false }];
    case 'TOGGLE':
      return state.map(todo =>
        todo.id === action.id ? { ...todo, done: !todo.done } : todo
      );
    case 'DELETE':
      return state.filter(todo => todo.id !== action.id);
    default:
      return state;
  }
}

function TodoApp() {
  const [todos, dispatch] = useReducer(todoReducer, []);
  const [text, setText] = useState('');

  const addTodo = () => {
    dispatch({ type: 'ADD', text });
    setText('');
  };

  return (
    &lt;div&gt;
      &lt;input value={text} onChange={e => setText(e.target.value)} /&gt;
      &lt;button onClick={addTodo}&gt;Добавить&lt;/button&gt;

      {todos.map(todo => (
        &lt;div key={todo.id}&gt;
          &lt;input
            type="checkbox"
            checked={todo.done}
            onChange={() => dispatch({ type: 'TOGGLE', id: todo.id })}
          /&gt;
          {todo.text}
          &lt;button onClick={() => dispatch({ type: 'DELETE', id: todo.id })}&gt;
            ✕
          &lt;/button&gt;
        &lt;/div&gt;
      ))}
    &lt;/div&gt;
  );
}</code>

💾 <b>useMemo — мемоизация вычислений</b>

<b>❌ Без useMemo (медленно):</b>
<code>function ProductList({ products, filter }) {
  // Фильтрация при КАЖДОМ рендере!
  const filtered = products.filter(p => p.category === filter);

  return &lt;div&gt;{filtered.map(...)}&lt;/div&gt;
}</code>

<b>✅ С useMemo (быстро):</b>
<code>function ProductList({ products, filter }) {
  // Фильтрация только при изменении products или filter
  const filtered = useMemo(() => {
    console.log('Фильтрация...');
    return products.filter(p => p.category === filter);
  }, [products, filter]);

  return &lt;div&gt;{filtered.map(...)}&lt;/div&gt;
}</code>

<b>Пример — тяжёлые вычисления:</b>
<code>function Fibonacci({ n }) {
  const result = useMemo(() => {
    // Тяжёлая рекурсия
    const fib = (num) => num <= 1 ? num : fib(num - 1) + fib(num - 2);
    return fib(n);
  }, [n]);

  return &lt;div&gt;Fibonacci({n}) = {result}&lt;/div&gt;
}</code>

🎯 <b>Когда использовать:</b>
• Тяжёлые вычисления
• Фильтрация/сортировка больших массивов
• Создание объектов/массивов для пропсов

🔄 <b>useMemo vs useCallback</b>

<b>useMemo — мемоизирует РЕЗУЛЬТАТ:</b>
<code>const expensiveValue = useMemo(() => {
  return computeExpensiveValue(a, b);
}, [a, b]);
// Возвращает: результат вычисления</code>

<b>useCallback — мемоизирует ФУНКЦИЮ:</b>
<code>const memoizedCallback = useCallback(() => {
  doSomething(a, b);
}, [a, b]);
// Возвращает: саму функцию</code>

<b>Практический пример:</b>
<code>function Parent() {
  const [count, setCount] = useState(0);
  const [text, setText] = useState('');

  // ❌ Создаётся новая функция при каждом рендере
  const handleClick = () => console.log('Click');

  // ✅ Функция создаётся один раз
  const handleClickMemo = useCallback(() => {
    console.log('Click');
  }, []);

  return (
    &lt;div&gt;
      &lt;input value={text} onChange={e => setText(e.target.value)} /&gt;
      &lt;Child onClick={handleClickMemo} /&gt; {/* Не перерисуется */}
    &lt;/div&gt;
  );
}

const Child = React.memo(({ onClick }) => {
  console.log('Child render');
  return &lt;button onClick={onClick}&gt;Кнопка&lt;/button&gt;
});</code>

💡 <b>Правило:</b>
useCallback(fn, deps) === useMemo(() => fn, deps)

⚡ <b>useLayoutEffect — синхронный эффект</b>

<b>Разница с useEffect:</b>
<code>// useEffect — асинхронный
useEffect(() => {
  // Выполняется ПОСЛЕ отрисовки на экране
}, []);

// useLayoutEffect — синхронный
useLayoutEffect(() => {
  // Выполняется ДО отрисовки на экране
}, []);</code>

<b>Пример проблемы с useEffect:</b>
<code>function Tooltip() {
  const [position, setPosition] = useState({ top: 0, left: 0 });
  const ref = useRef();

  useEffect(() => {
    const rect = ref.current.getBoundingClientRect();
    setPosition({ top: rect.bottom, left: rect.left });
  }, []);

  // ⚠️ Мигание! Сначала рендер в (0,0), потом обновление
  return &lt;div ref={ref} style={position}&gt;Tooltip&lt;/div&gt;
}</code>

<b>✅ Решение с useLayoutEffect:</b>
<code>useLayoutEffect(() => {
  const rect = ref.current.getBoundingClientRect();
  setPosition({ top: rect.bottom, left: rect.left });
}, []);
// Позиция вычисляется ДО отрисовки — нет мигания!</code>

🎯 <b>Когда использовать:</b>
• Измерение DOM
• Синхронизация с DOM
• Предотвращение мигания

⚠️ <b>Осторожно:</b> Блокирует отрисовку! Используйте редко.

💾 <b>Кастомный хук useLocalStorage</b>

<code>function useLocalStorage(key, initialValue) {
  // Получаем значение из localStorage или используем начальное
  const [value, setValue] = useState(() => {
    try {
      const item = window.localStorage.getItem(key);
      return item ? JSON.parse(item) : initialValue;
    } catch (error) {
      console.error(error);
      return initialValue;
    }
  });

  // Сохраняем в localStorage при изменении
  const setStoredValue = (newValue) => {
    try {
      setValue(newValue);
      window.localStorage.setItem(key, JSON.stringify(newValue));
    } catch (error) {
      console.error(error);
    }
  };

  return [value, setStoredValue];
}

// Использование:
function App() {
  const [name, setName] = useLocalStorage('userName', 'Гость');
  const [theme, setTheme] = useLocalStorage('theme', 'light');

  return (
    &lt;div&gt;
      &lt;input value={name} onChange={e => setName(e.target.value)} /&gt;
      &lt;button onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')}&gt;
        Тема: {theme}
      &lt;/button&gt;
    &lt;/div&gt;
  );
}</code>

🌐 <b>Кастомный хук useFetch</b>

<code>function useFetch(url) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    let cancelled = false;

    const fetchData = async () => {
      setLoading(true);
      setError(null);

      try {
        const response = await fetch(url);
        if (!response.ok) throw new Error('Ошибка загрузки');
        const json = await response.json();

        if (!cancelled) {
          setData(json);
          setLoading(false);
        }
      } catch (err) {
        if (!cancelled) {
          setError(err.message);
          setLoading(false);
        }
      }
    };

    fetchData();
    return () => { cancelled = true; };
  }, [url]);

  return { data, loading, error };
}

// Использование:
function UserProfile({ userId }) {
  const { data, loading, error } = useFetch(`/api/users/${userId}`);

  if (loading) return &lt;div&gt;Загрузка...&lt;/div&gt;
  if (error) return &lt;div&gt;Ошибка: {error}&lt;/div&gt;
  return &lt;div&gt;{data.name}&lt;/div&gt;
}</code>

🔄 <b>Кастомный хук useToggle</b>

<code>function useToggle(initialValue = false) {
  const [value, setValue] = useState(initialValue);

  const toggle = useCallback(() => {
    setValue(v => !v);
  }, []);

  return [value, toggle];
}

// Использование:
function Modal() {
  const [isOpen, toggleOpen] = useToggle(false);

  return (
    &lt;div&gt;
      &lt;button onClick={toggleOpen}&gt;Открыть модалку&lt;/button&gt;

      {isOpen && (
        &lt;div className="modal"&gt;
          &lt;h2&gt;Модальное окно&lt;/h2&gt;
          &lt;button onClick={toggleOpen}&gt;Закрыть&lt;/button&gt;
        &lt;/div&gt;
      )}
    &lt;/div&gt;
  );
}

// Расширенная версия:
function useToggle(initialValue = false) {
  const [value, setValue] = useState(initialValue);

  const toggle = useCallback(() => setValue(v => !v), []);
  const setTrue = useCallback(() => setValue(true), []);
  const setFalse = useCallback(() => setValue(false), []);

  return [value, { toggle, setTrue, setFalse }];
}</code>

⏱️ <b>Кастомный хук useDebounce</b>

<code>function useDebounce(value, delay) {
  const [debouncedValue, setDebouncedValue] = useState(value);

  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedValue(value);
    }, delay);

    return () => clearTimeout(timer); // Очистка таймера
  }, [value, delay]);

  return debouncedValue;
}

// Использование в поиске:
function SearchComponent() {
  const [searchTerm, setSearchTerm] = useState('');
  const debouncedSearch = useDebounce(searchTerm, 500); // 500мс задержка
  const [results, setResults] = useState([]);

  useEffect(() => {
    if (debouncedSearch) {
      // API запрос только после 500мс бездействия
      fetch(`/api/search?q=${debouncedSearch}`)
        .then(res => res.json())
        .then(setResults);
    }
  }, [debouncedSearch]);

  return (
    &lt;div&gt;
      &lt;input
        value={searchTerm}
        onChange={e => setSearchTerm(e.target.value)}
        placeholder="Поиск..."
      /&gt;
      &lt;ul&gt;{results.map(r => &lt;li key={r.id}&gt;{r.name}&lt;/li&gt;)}&lt;/ul&gt;
    &lt;/div&gt;
  );
}</code>

⏮️ <b>Кастомный хук usePrevious</b>

<code>function usePrevious(value) {
  const ref = useRef();

  useEffect(() => {
    ref.current = value; // Сохраняем текущее значение
  }, [value]);

  return ref.current; // Возвращаем предыдущее
}

// Использование:
function Counter() {
  const [count, setCount] = useState(0);
  const prevCount = usePrevious(count);

  return (
    &lt;div&gt;
      &lt;p&gt;Текущее: {count}&lt;/p&gt;
      &lt;p&gt;Предыдущее: {prevCount}&lt;/p&gt;
      &lt;button onClick={() => setCount(count + 1)}&gt;+1&lt;/button&gt;
    &lt;/div&gt;
  );
}

// Пример — отслеживание изменений:
function UserProfile({ userId }) {
  const prevUserId = usePrevious(userId);

  useEffect(() => {
    if (prevUserId && prevUserId !== userId) {
      console.log(`Переход от пользователя ${prevUserId} к ${userId}`);
    }
  }, [userId, prevUserId]);

  return &lt;div&gt;User ID: {userId}&lt;/div&gt;
}</code>

🖱️ <b>Кастомный хук useClickOutside</b>

<code>function useClickOutside(ref, callback) {
  useEffect(() => {
    const handleClick = (event) => {
      if (ref.current && !ref.current.contains(event.target)) {
        callback(); // Клик вне элемента
      }
    };

    document.addEventListener('mousedown', handleClick);
    return () => document.removeEventListener('mousedown', handleClick);
  }, [ref, callback]);
}

// Использование:
function Modal({ isOpen, onClose }) {
  const modalRef = useRef();
  useClickOutside(modalRef, onClose);

  if (!isOpen) return null;

  return (
    &lt;div className="overlay"&gt;
      &lt;div ref={modalRef} className="modal"&gt;
        &lt;h2&gt;Модальное окно&lt;/h2&gt;
        &lt;p&gt;Кликните вне окна, чтобы закрыть&lt;/p&gt;
        &lt;button onClick={onClose}&gt;Закрыть&lt;/button&gt;
      &lt;/div&gt;
    &lt;/div&gt;
  );
}

function App() {
  const [isOpen, setIsOpen] = useState(false);

  return (
    &lt;div&gt;
      &lt;button onClick={() => setIsOpen(true)}&gt;Открыть&lt;/button&gt;
      &lt;Modal isOpen={isOpen} onClose={() => setIsOpen(false)} /&gt;
    &lt;/div&gt;
  );
}</code>

📋 <b>Правила хуков (Rules of Hooks)</b>

<b>1️⃣ Вызывайте хуки только на верхнем уровне</b>
<code>// ❌ Плохо
function Component() {
  if (condition) {
    const [state, setState] = useState(0); // Ошибка!
  }
}

// ✅ Хорошо
function Component() {
  const [state, setState] = useState(0);
  if (condition) {
    // Используйте state здесь
  }
}</code>

<b>2️⃣ Вызывайте хуки только в функциональных компонентах или кастомных хуках</b>
<code>// ❌ Плохо
function regularFunction() {
  const [state, setState] = useState(0); // Ошибка!
}

// ✅ Хорошо
function useCustomHook() {
  const [state, setState] = useState(0); // OK
  return state;
}</code>

<b>3️⃣ Не вызывайте в циклах, условиях или вложенных функциях</b>
<code>// ❌ Плохо
items.forEach(() => {
  const [state] = useState(0); // Ошибка!
});</code>

💡 <b>Почему:</b> React полагается на порядок вызова хуков для сохранения состояния между рендерами

📦 <b>Batching — группировка обновлений состояния</b>

<b>React 17 и ранее:</b>
<code>function handleClick() {
  setCount(c => c + 1);
  setFlag(f => !f);
  // ✅ 1 рендер (батчинг работает в обработчиках событий)
}

fetch('/api').then(() => {
  setCount(c => c + 1);
  setFlag(f => !f);
  // ❌ 2 рендера (батчинг НЕ работает в промисах)
});</code>

<b>React 18 — Automatic Batching:</b>
<code>function handleClick() {
  setCount(c => c + 1);
  setFlag(f => !f);
  // ✅ 1 рендер
}

fetch('/api').then(() => {
  setCount(c => c + 1);
  setFlag(f => !f);
  // ✅ 1 рендер (теперь работает везде!)
});

setTimeout(() => {
  setCount(c => c + 1);
  setFlag(f => !f);
  // ✅ 1 рендер
}, 1000);</code>

<b>Отключить батчинг (редко нужно):</b>
<code>import { flushSync } from 'react-dom';

flushSync(() => {
  setCount(c => c + 1); // Рендер сразу
});
flushSync(() => {
  setFlag(f => !f); // Ещё один рендер
});</code>

🎯 <b>Преимущество:</b> Меньше рендеров = лучше производительность!

